package main

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5"
)

type curatedExtraTask struct {
	topic      string
	kind       string
	text       string
	answer     string
	short      string
	difficulty int
}

func curatedQuestionType(kind string) string {
	switch kind {
	case "ikr":
		return "explain"
	case "tkr":
		return "prove"
	default:
		return ""
	}
}

var curatedExtraTasks = []curatedExtraTask{
	{"Предел последовательности", "ikr", `Вычислить \(\lim_{n\to\infty}\frac{3n^2-2n+1}{2n^2+5n-4}\). Обосновать переход к пределу.`, `Разделим числитель и знаменатель на \(n^2\), что допустимо при \(n\ge1\): \(\frac{3n^2-2n+1}{2n^2+5n-4}=\frac{3-2/n+1/n^2}{2+5/n-4/n^2}\). По определению предела последовательности \(1/n\to0\), поэтому числитель стремится к 3, знаменатель — к 2. Так как предел знаменателя ненулевой, по теореме о пределе частного предел равен \(3/2\).`, "деление на n²; ненулевой предел знаменателя; предел 3/2", 2},
	{"Предел последовательности", "tkr", `Доказать единственность предела сходящейся последовательности.`, `Предположим, что последовательность \((a_n)\) имеет два предела \(a\) и \(b\). Если \(a\ne b\), положим \(\varepsilon=|a-b|/3>0\). Из \(a_n\to a\) существует \(N_1\), а из \(a_n\to b\) существует \(N_2\), такие что при \(n\ge N_1\) выполнено \(|a_n-a|<\varepsilon\), а при \(n\ge N_2\) — \(|a_n-b|<\varepsilon\). Для \(n\ge\max(N_1,N_2)\) неравенство треугольника даёт \(|a-b|\le|a-a_n|+|a_n-b|<2\varepsilon=2|a-b|/3\), что противоречит \(|a-b|>0\). Значит, предположение неверно и \(a=b\).`, "предположение двух пределов; epsilon = расстояние/3; неравенство треугольника; противоречие", 3},
	{"Монотонные ограниченные последовательности", "ikr", `Для \(a_1=1\), \(a_{n+1}=\frac{a_n+2}{2}\) доказать сходимость и найти предел.`, `Имеем \(a_1=1\). Если \(1\le a_n<2\), то \(a_{n+1}=(a_n+2)/2\) удовлетворяет \(1\le a_{n+1}<2\). По индукции \(1\le a_n<2\) для всех \(n\). Кроме того, \(a_{n+1}-a_n=(2-a_n)/2>0\), поэтому последовательность возрастает и ограничена сверху числом 2. По теореме о сходимости монотонной ограниченной последовательности существует предел \(L\). Переходя к пределу в рекуррентном равенстве, получаем \(L=(L+2)/2\), откуда \(L=2\).`, "индуктивная оценка 1≤aₙ<2; монотонность; ограниченность; предельное уравнение L=2", 3},
	{"Монотонные ограниченные последовательности", "tkr", `Доказать теорему: всякая возрастающая и ограниченная сверху последовательность сходится к точной верхней грани множества её членов.`, `Пусть \((a_n)\) возрастает и ограничена сверху. Множество \(A=\{a_n:n\in\mathbb N\}\) непусто и ограничено сверху, поэтому по полноте \(\mathbb R\) существует \(s=\sup A\). Зафиксируем произвольное \(\varepsilon>0\). Число \(s-\varepsilon\) не является верхней гранью \(A\), иначе оно было бы верхней гранью, меньшей наименьшей верхней грани \(s\). Поэтому найдётся номер \(N\), для которого \(a_N>s-\varepsilon\). При \(n\ge N\), ввиду возрастания, \(a_n\ge a_N>s-\varepsilon\); также \(a_n\le s\), поскольку \(s\) — верхняя грань. Следовательно, \(0\le s-a_n<\varepsilon\), то есть \(|a_n-s|<\varepsilon\). Это верно для любого \(\varepsilon>0\), значит, \(a_n\to s\).`, "sup множества; s−ε не верхняя грань; монотонность; определение предела", 4},
	{"Фундаментальные последовательности и критерий Коши", "ikr", `Проверить по определению критерия Коши, что последовательность \(a_n=1/n\) фундаментальна.`, `Пусть \(\varepsilon>0\). Выберем натуральное \(N>2/\varepsilon\). Для любых \(m,n\ge N\) имеем \(|1/n-1/m|=|m-n|/(mn)\le1/\min(m,n)\le1/N<\varepsilon/2<\varepsilon\). Значит, для каждого \(\varepsilon>0\) найден номер \(N\), после которого расстояние между любыми двумя членами меньше \(\varepsilon\). Это и есть определение фундаментальности; следовательно, \((1/n)\) фундаментальна.`, "произвольное epsilon; N>2/epsilon; оценка разности; критерий Коши", 2},
	{"Фундаментальные последовательности и критерий Коши", "tkr", `Доказать критерий Коши для последовательностей в \(\mathbb R\): последовательность сходится тогда и только тогда, когда она фундаментальна.`, `Если \(a_n\to a\), то для заданного \(\varepsilon>0\) найдётся \(N\), что при \(n\ge N\) выполнено \(|a_n-a|<\varepsilon/2\). Тогда для любых \(m,n\ge N\) \(|a_n-a_m|\le|a_n-a|+|a_m-a|<\varepsilon\), и последовательность фундаментальна. Обратно, пусть \((a_n)\) фундаментальна. Она ограничена: для \(\varepsilon=1\) начиная с некоторого \(N\) все члены отличаются от \(a_N\) менее чем на 1, а первые конечное число членов также ограничено. По теореме Больцано—Вейерштрасса из ограниченной последовательности можно выделить сходящуюся подпоследовательность \(a_{n_k}\to a\). Докажем сходимость всей последовательности. Для заданного \(\varepsilon>0\) фундаментальность даёт \(N_1\), при котором \(|a_n-a_m|<\varepsilon/2\) для \(m,n\ge N_1\). Выберем \(k\) так, чтобы \(n_k\ge N_1\) и \(|a_{n_k}-a|<\varepsilon/2\). Тогда для любого \(n\ge N_1\) \(|a_n-a|\le|a_n-a_{n_k}|+|a_{n_k}-a|<\varepsilon\). Следовательно, \(a_n\to a\).`, "сходимость влечёт Коши; фундаментальная ограничена; Больцано—Вейерштрасс; сходимость всей последовательности", 5},
	{"Предел функции и критерий Гейне", "ikr", `Вычислить \(\lim_{x\to2}\frac{x^2-4}{x-2}\) и доказать результат по определению.`, `При \(x\ne2\) дробь равна \(x+2\). Предполагаемый предел равен 4. Для любого \(\varepsilon>0\) выберем \(\delta=\varepsilon\). Если \(0<|x-2|<\delta\), то \(|(x^2-4)/(x-2)-4|=|x+2-4|=|x-2|<\varepsilon\). Следовательно, по определению Коши \(\lim_{x\to2}(x^2-4)/(x-2)=4\).`, "сокращение при x≠2; epsilon-delta; δ=ε; предел 4", 2},
	{"Предел функции и критерий Гейне", "tkr", `Доказать критерий Гейне существования конечного предела функции в точке.`, `Пусть \(x_0\) — предельная точка области определения функции. Если \(\lim_{x\to x_0}f(x)=A\), то для любой последовательности \(x_n\ne x_0\), \(x_n\to x_0\), и любого \(\varepsilon>0\) определение предела функции даёт \(\delta>0\), при котором \(0<|x-x_0|<\delta\Rightarrow|f(x)-A|<\varepsilon\). Для достаточно больших \(n\) выполнено \(0<|x_n-x_0|<\delta\), значит, \(f(x_n)\to A\). Обратно, предположим, что для любой такой последовательности \(f(x_n)\to A\), но предел функции не равен \(A\). Тогда найдётся \(\varepsilon_0>0\), для которого при каждом \(k\) существует точка \(x_k\) области определения с \(0<|x_k-x_0|<1/k\) и \(|f(x_k)-A|\ge\varepsilon_0\). Полученная последовательность стремится к \(x_0\), но её образы не стремятся к \(A\), противоречие. Следовательно, предел функции равен \(A\).`, "прямая импликация; обратная через отрицание epsilon-delta; последовательность-контрпример", 5},
	{"Односторонние и бесконечные пределы", "ikr", `Вычислить \(\lim_{x\to0+}\frac{1}{\sqrt{x}}\) и доказать, что предел равен \(+\infty\).`, `По определению бесконечного предела требуется показать: для каждого \(M>0\) найдётся \(\delta>0\), что из \(0<x<\delta\) следует \(1/\sqrt{x}>M\). Возьмём \(\delta=1/M^2\). Тогда \(0<x<\delta\) влечёт \(\sqrt{x}<1/M\), а значит, \(1/\sqrt{x}>M\). Следовательно, \(\lim_{x\to0+}1/\sqrt{x}=+\infty\).`, "определение +∞; любое M>0; δ=1/M²", 2},
	{"Односторонние и бесконечные пределы", "tkr", `Доказать критерий Коши существования конечного предела функции в точке через колебание значений в проколотой окрестности.`, `Пусть \(x_0\) — предельная точка области определения. Конечный предел существует тогда и только тогда, когда для любого \(\varepsilon>0\) существует \(\delta>0\), такое что для любых \(x,y\) из области определения с \(0<|x-x_0|<\delta\) и \(0<|y-x_0|<\delta\) выполнено \(|f(x)-f(y)|<\varepsilon\). Необходимость: если \(f(x)\to A\), выберем окрестность, в которой \(|f(x)-A|<\varepsilon/2\); тогда \(|f(x)-f(y)|<\varepsilon\). Достаточность: выберем последовательность \(x_n\to x_0\), \(x_n\ne x_0\). Условие Коши для функции показывает, что \((f(x_n))\) фундаментальна, поэтому в \(\mathbb R\) сходится к некоторому \(A\). Для любой другой последовательности \(y_n\to x_0\), применяя условие к парам \((x_n,y_n)\), получаем \(|f(x_n)-f(y_n)|\to0\), поэтому \(f(y_n)\to A\). По критерию Гейне предел функции существует и равен \(A\).`, "условие Коши для пары точек; необходимость; полнота R; критерий Гейне", 5},
	{"Непрерывная функция", "ikr", `Исследовать непрерывность \(f(x)=\frac{x^2-1}{x-1}\) в точке \(x=1\) и указать, как доопределить функцию до непрерывной.`, `Область определения исходной функции не содержит \(x=1\). При \(x\ne1\) имеем \(f(x)=x+1\), поэтому \(\lim_{x\to1}f(x)=2\). В самой точке исходная функция не определена и потому не является непрерывной на множестве, содержащем 1. Определим \(\tilde f(x)=f(x)\) при \(x\ne1\) и \(\tilde f(1)=2\). Тогда \(\lim_{x\to1}\tilde f(x)=2=\tilde f(1)\), что по определению означает непрерывность \(\tilde f\) в точке 1.`, "предел 2; исходная функция не определена в 1; доопределение f(1)=2", 2},
	{"Непрерывная функция", "tkr", `Доказать теорему о промежуточных значениях непрерывной функции на отрезке.`, `Пусть \(f\) непрерывна на \([a,b]\), а число \(C\) лежит между \(f(a)\) и \(f(b)\). Для случая \(f(a)<C<f(b)\) положим \(S=\{x\in[a,b]:f(x)\le C\}\). Множество непусто (содержит \(a\)) и ограничено сверху числом \(b\), поэтому существует \(c=\sup S\in[a,b]\). Если \(f(c)<C\), непрерывность даёт окрестность \(c\), в которой \(f(x)<C\); при \(c<b\) это даёт точки правее \(c\), принадлежащие \(S\), противоречие верхней грани. Если \(f(c)>C\), непрерывность даёт окрестность, в которой \(f(x)>C\); тогда все точки S лежат левее некоторого числа, меньшего c, что противоречит определению супремума. Следовательно, \(f(c)=C\). Случай \(f(a)>C>f(b)\) доказывается применением результата к \(-f\); равенство C одному из крайних значений выполняется в соответствующем конце отрезка.`, "множество S; супремум; непрерывность исключает f(c)<C и f(c)>C; заключение", 5},
	{"Классификация точек разрыва", "ikr", `Для \(f(x)=\frac{x^2-1}{x-1}\) при \(x\ne1\), классифицировать точку \(x=1\) и построить непрерывное доопределение.`, `Для \(x\ne1\) функция равна \(x+1\), поэтому оба односторонних предела в точке 1 существуют и равны 2. Значение функции в точке 1 отсутствует. Следовательно, это устранимый разрыв: конечный общий предел существует, но функция не определена в точке. Положив \(f(1)=2\), устраняем разрыв, поскольку после доопределения предел равен значению функции.`, "оба односторонних предела равны 2; значение не определено; устранимый разрыв", 2},
	{"Классификация точек разрыва", "tkr", `Доказать, что если у функции в точке существуют конечные односторонние пределы, то она непрерывна в этой точке тогда и только тогда, когда оба предела равны значению функции.`, `Пусть существуют \(L_- =\lim_{x\to x_0-}f(x)\), \(L_+=\lim_{x\to x_0+}f(x)\), а \(f(x_0)\) определено. Если функция непрерывна в \(x_0\), то по определению \(\lim_{x\to x_0}f(x)=f(x_0)\). Ограничение того же предела слева и справа даёт \(L_-=L_+=f(x_0)\). Обратно, пусть оба односторонних предела равны \(f(x_0)\). Для любого \(\varepsilon>0\) найдутся \(\delta_-,\delta_+>0\), обеспечивающие соответствующую оценку слева и справа. Положим \(\delta=\min(\delta_-,\delta_+)\). Тогда при \(0<|x-x_0|<\delta\), независимо от знака \(x-x_0\), выполняется \(|f(x)-f(x_0)|<\varepsilon\). Это определение непрерывности в точке.`, "необходимость односторонними пределами; δ=min; достаточность определением", 4},
	{"Определение производной", "ikr", `По определению найти производную \(f(x)=x^2\) в произвольной точке \(x_0\).`, `По определению \(f'(x_0)=\lim_{h\to0}\frac{(x_0+h)^2-x_0^2}{h}\). При \(h\ne0\) числитель равен \(2x_0h+h^2\), поэтому разностное отношение равно \(2x_0+h\). Переходя к пределу при \(h\to0\), получаем \(f'(x_0)=2x_0\). Поскольку \(x_0\) произвольна, \(f'(x)=2x\) на всей числовой прямой.`, "разностное отношение; сокращение h; предел 2x₀", 2},
	{"Определение производной", "tkr", `Из определения производной доказать, что дифференцируемость функции в точке влечёт её непрерывность в этой точке.`, `Пусть \(f\) дифференцируема в \(x_0\), то есть существует конечный предел \(f'(x_0)=\lim_{h\to0}\frac{f(x_0+h)-f(x_0)}h\). Для \(h\ne0\) запишем \(f(x_0+h)-f(x_0)=h\frac{f(x_0+h)-f(x_0)}h\). Первый множитель стремится к нулю, второй — к конечному числу \(f'(x_0)\), поэтому их произведение стремится к нулю. Значит, \(\lim_{h\to0}f(x_0+h)=f(x_0)\), что является определением непрерывности в \(x_0\).`, "разложение приращения; предел h равен 0; предел отношения конечен; непрерывность", 4},
	{"Производные элементарных функций", "ikr", `Найти производную \(f(x)=\sin x+x^3\) и обосновать применённые формулы.`, `Функции \(\sin x\) и \(x^3\) дифференцируемы при всех \(x\). По линейности производной \(f'(x)=(\sin x)'+(x^3)'\). Из стандартных производных элементарных функций \((\sin x)'=\cos x\), а по правилу степени \((x^3)'=3x^2\). Следовательно, \(f'(x)=\cos x+3x^2\) для каждого \(x\in\mathbb R\).`, "линейность; производная sin; правило степени", 2},
	{"Производные элементарных функций", "tkr", `Вывести правило дифференцирования произведения двух функций из определения производной.`, `Пусть \(f,g\) дифференцируемы в \(x\). Для приращения \(h\ne0\) имеем \(f(x+h)g(x+h)-f(x)g(x)=f(x+h)(g(x+h)-g(x))+g(x)(f(x+h)-f(x))\). Делим на \(h\): разностное отношение произведения равно \(f(x+h)\frac{g(x+h)-g(x)}h+g(x)\frac{f(x+h)-f(x)}h\). Дифференцируемость влечёт непрерывность, поэтому при \(h\to0\) имеем \(f(x+h)\to f(x)\), а разностные отношения стремятся к \(g'(x)\) и \(f'(x)\). Следовательно, \((fg)'(x)=f(x)g'(x)+f'(x)g(x)\).`, "разложение приращения произведения; пределы разностных отношений; непрерывность; формула Лейбница", 4},
	{"Дифференцируемая функция и дифференциал", "ikr", `Для \(f(x)=x^2+1\) в точке \(x=3\) записать дифференциал и оценить приращение при \(dx=0{,}1\).`, `Производная равна \(f'(x)=2x\), следовательно, в точке 3 дифференциал \(df=f'(3)dx=6dx\). При \(dx=0{,}1\) линейная часть приращения равна \(df=0{,}6\). Точное приращение: \(f(3+0{,}1)-f(3)=3{,}1^2+1-(3^2+1)=9{,}61-9=0{,}61\). Остаток равен \(0{,}61-0{,}6=0{,}01=(dx)^2\), что подтверждает разложение \(\Delta f=df+o(dx)\) при \(dx\to0\).`, "df=6dx; точное приращение 0,61; остаток 0,01=(dx)²", 2},
	{"Дифференцируемая функция и дифференциал", "tkr", `Доказать критерий дифференцируемости функции одной переменной: \(f\) дифференцируема в \(x_0\) тогда и только тогда, когда \(\Delta f=A h+o(h)\).`, `Если производная существует и равна \(A\), то для \(h\ne0\) положим \(\alpha(h)=\frac{f(x_0+h)-f(x_0)}h-A\). По определению производной \(\alpha(h)\to0\). Тогда \(\Delta f=Ah+h\alpha(h)=Ah+o(h)\). Обратно, если \(\Delta f=Ah+r(h)\), где \(r(h)/h\to0\), то при \(h\ne0\) \(\frac{f(x_0+h)-f(x_0)}h=A+\frac{r(h)}h\to A\). Следовательно, производная существует и равна \(A\). Коэффициент \(A\) единственен: если также \(\Delta f=Bh+o(h)\), деление на \(h\) и переход к пределу дают \(A=B\).`, "производная даёт остаток o(h); обратное делением на h; единственность A", 5},
	{"Производные и дифференциалы высших порядков", "ikr", `Найти первую и вторую производные функции \(f(x)=x^4-2x^2+1\).`, `Применяя правило степени к каждому слагаемому, получаем \(f'(x)=4x^3-4x\). Дифференцируем ещё раз: \(f''(x)=12x^2-4\). Проверка: производная константы равна нулю, а производная \(-2x^2\) равна \(-4x\), поэтому приведённые выражения получены корректно для всех \(x\in\mathbb R\).`, "производная 4x³−4x; вторая производная 12x²−4", 2},
	{"Производные и дифференциалы высших порядков", "tkr", `Доказать формулу Лейбница для n-й производной произведения \((fg)^{(n)}\).`, `Формула имеет вид \((fg)^{(n)}=\sum_{k=0}^{n}\binom nk f^{(k)}g^{(n-k)}\). Для \(n=1\) она совпадает с правилом произведения. Предположим, что формула верна для некоторого \(n\). Дифференцируем сумму по правилу произведения: получаем суммы \(\sum_{k=0}^{n}\binom nk f^{(k+1)}g^{(n-k)}\) и \(\sum_{k=0}^{n}\binom nk f^{(k)}g^{(n-k+1)}\). В коэффициенте при \(f^{(j)}g^{(n+1-j)}\), для \(1\le j\le n\), складываются \(\binom n{j-1}+\binom nj=\binom{n+1}j\) по тождеству Паскаля; крайние коэффициенты равны 1. Значит, получается формула для \(n+1\). По индукции она верна для всех натуральных \(n\), если функции имеют соответствующие производные.`, "база n=1; дифференцирование суммы; тождество Паскаля; индукционный вывод", 5},
	{"Свойства дифференцируемых функций", "ikr", `По теореме Лагранжа оценить \(|\sqrt{4.1}-2|\).`, `Пусть \(f(x)=\sqrt{x}\) на отрезке \([4,4.1]\). Функция непрерывна на отрезке и дифференцируема внутри него, причём \(f'(x)=1/(2\sqrt{x})\). По теореме Лагранжа существует \(c\in(4,4.1)\), такое что \(\sqrt{4.1}-2=f'(c)\cdot0.1=0.1/(2\sqrt c)\). Так как \(c>4\), имеем \(2\sqrt c>4\), откуда \(0<\sqrt{4.1}-2<0.025\).`, "условия Лагранжа; точка c; производная; оценка меньше 0,025", 3},
	{"Свойства дифференцируемых функций", "tkr", `Доказать теорему Лагранжа о конечных приращениях.`, `Пусть \(f\) непрерывна на \([a,b]\) и дифференцируема на \((a,b)\), где \(a<b\). Рассмотрим \(\varphi(x)=f(x)-f(a)-\frac{f(b)-f(a)}{b-a}(x-a)\). Функция непрерывна на \([a,b]\), дифференцируема на \((a,b)\), и \(\varphi(a)=\varphi(b)=0\). По теореме Ролля существует \(c\in(a,b)\) с \(\varphi'(c)=0\). Но \(\varphi'(x)=f'(x)-\frac{f(b)-f(a)}{b-a}\), следовательно, \(f'(c)=\frac{f(b)-f(a)}{b-a}\), или \(f(b)-f(a)=f'(c)(b-a)\).`, "вспомогательная функция; равенство на концах; Ролль; формула Лагранжа", 4},
	{"Правило Лопиталя", "ikr", `Вычислить \(\lim_{x\to0}\frac{e^x-1}{x}\), указав проверку условий правила Лопиталя.`, `При \(x\to0\) числитель и знаменатель стремятся к нулю. Функции \(e^x-1\) и \(x\) дифференцируемы в проколотой окрестности нуля, производная знаменателя равна 1 и не обращается в ноль. По правилу Лопиталя предел исходного отношения равен \(\lim_{x\to0}e^x/1=1\), поскольку экспонента непрерывна в нуле. Итак, предел равен 1.`, "неопределённость 0/0; дифференцируемость; производная знаменателя ненулевая; предел 1", 3},
	{"Правило Лопиталя", "tkr", `Сформулировать правило Лопиталя для неопределённости \(0/0\) при конечном пределе отношения производных и доказать его.`, `Пусть \(f,g\) непрерывны в \(a\), дифференцируемы в проколотой окрестности \(a\), \(f(a)=g(a)=0\), \(g(x)\ne0\) и \(g'(x)\ne0\) при \(0<|x-a|<\delta_0\), а \(\lim_{x\to a}f'(x)/g'(x)=L\in\mathbb R\). Возьмём любое \(x\ne a\), достаточно близкое к \(a\). По теореме Коши о среднем значении на отрезке с концами \(a,x\) существует \(c_x\) между ними, для которого \(\frac{f(x)-f(a)}{g(x)-g(a)}=\frac{f'(c_x)}{g'(c_x)}\). Так как \(f(a)=g(a)=0\), левая часть равна \(f(x)/g(x)\). При \(x\to a\) имеем \(|c_x-a|\le|x-a|\to0\), поэтому \(c_x\to a\); по условию отношение производных в \(c_x\) стремится к \(L\). Следовательно, \(f(x)/g(x)\to L\), что и требовалось доказать.`, "условия 0/0; теорема Коши; c между a и x; предел отношений производных", 5},
	{"Формула Тейлора", "ikr", `Разложить \(e^x\) около нуля до второго порядка с остатком Пеано и вычислить \(\lim_{x\to0}\frac{e^x-1-x}{x^2}\).`, `Функция \(e^x\) дважды дифференцируема в окрестности нуля, причём \(f(0)=f'(0)=f''(0)=1\). Формула Тейлора с остатком Пеано даёт \(e^x=1+x+x^2/2+o(x^2)\) при \(x\to0\). Поэтому \((e^x-1-x)/x^2=1/2+o(1)\), и предел равен \(1/2\).`, "значения производных в 0; формула Тейлора; деление на x²; предел 1/2", 3},
	{"Формула Тейлора", "tkr", `Доказать формулу Тейлора с остатком Пеано порядка n для функции \(f\in C^n\) в окрестности точки \(x_0\).`, `Пусть \(h=x-x_0\). При \(n\ge1\) многократное применение основной теоремы анализа даёт формулу с интегральным остатком: \(f(x_0+h)=\sum_{k=0}^{n-1}\frac{f^{(k)}(x_0)}{k!}h^k+\frac1{(n-1)!}\int_0^h(h-t)^{n-1}f^{(n)}(x_0+t)\,dt\). Выделим в интеграле значение \(f^{(n)}(x_0)\). Поскольку \(\frac1{(n-1)!}\int_0^h(h-t)^{n-1}\,dt=\frac{h^n}{n!}\), получаем \(f(x_0+h)=\sum_{k=0}^{n}\frac{f^{(k)}(x_0)}{k!}h^k+R(h)\), где \(R(h)=\frac1{(n-1)!}\int_0^h(h-t)^{n-1}[f^{(n)}(x_0+t)-f^{(n)}(x_0)]\,dt\). Для \(h\ne0\), используя непрерывность \(f^{(n)}\) в \(x_0\), имеем \(\frac{|R(h)|}{|h|^n}\le\frac1{n!}\sup_{|t|\le|h|}|f^{(n)}(x_0+t)-f^{(n)}(x_0)|\to0\). Значит, \(R(h)=o(h^n)\). Подстановка \(h=x-x_0\) даёт требуемую формулу; при \(n=0\) она следует из непрерывности \(f\).`, "интегральная формула остатка; выделение производной в точке; оценка через непрерывность; o(hⁿ)", 5},
	{"Локальные экстремумы функций одной переменной", "ikr", `Найти локальные экстремумы \(f(x)=x^3-3x\) и обосновать их характер.`, `Производная \(f'(x)=3x^2-3=3(x-1)(x+1)\), критические точки \(-1,1\). При \(x<-1\) производная положительна; при \(-1<x<1\) отрицательна; при \(x>1\) положительна. Следовательно, функция возрастает до \(-1\), убывает на \((-1,1)\), затем возрастает. Поэтому в \(x=-1\) локальный максимум, \(f(-1)=2\); в \(x=1\) локальный минимум, \(f(1)=-2\).`, "критические точки; знак производной; max в −1 равен 2; min в 1 равен −2", 3},
	{"Локальные экстремумы функций одной переменной", "tkr", `Доказать необходимое условие Ферма: если дифференцируемая в точке внутренняя функция имеет локальный экстремум, её производная в этой точке равна нулю.`, `Пусть \(x_0\) — внутренняя точка области определения, а \(f\) имеет в ней локальный максимум и дифференцируема. Для достаточно малых \(h>0\) имеем \(f(x_0+h)-f(x_0)\le0\), поэтому правое разностное отношение не превосходит нуля; переход к пределу даёт \(f'(x_0)\le0\). Для достаточно малых \(h<0\) числитель также неположителен, а знаменатель отрицателен, поэтому разностное отношение неотрицательно; переход к пределу даёт \(f'(x_0)\ge0\). Следовательно, \(f'(x_0)=0\). Для локального минимума неравенства меняют направление и дают те же два заключения. Условие необходимо, но не достаточно: например, \(f(x)=x^3\) имеет \(f'(0)=0\), но экстремума в нуле нет.`, "правые приращения; левые приращения; два неравенства; необходимое, не достаточное условие", 4},
}

func seedCuratedExtraTasks(ctx context.Context, db pgx.Tx) error {
	for _, task := range curatedExtraTasks {
		var topicID int
		if err := db.QueryRow(ctx, `select id from topics where title = $1`, task.topic).Scan(&topicID); err != nil {
			return fmt.Errorf("find topic for extra task %q: %w", task.topic, err)
		}
		text := task.text
		if _, err := db.Exec(ctx, `
			insert into questions (topic_id, type, exam_kind, text, expected_answer, short_answer, difficulty, tags, source)
			values ($1, $8, $2, $3, $4, $5, $6, $7, 'curated')
			on conflict (text) do update set topic_id = excluded.topic_id, type = excluded.type,
				exam_kind = excluded.exam_kind, expected_answer = excluded.expected_answer,
				short_answer = excluded.short_answer, difficulty = excluded.difficulty,
				tags = excluded.tags, source = excluded.source
		`, topicID, task.kind, text, task.answer, task.short, task.difficulty, []string{task.kind, "variant", "curated-extra"}, curatedQuestionType(task.kind)); err != nil {
			return fmt.Errorf("seed extra task %q: %w", task.topic, err)
		}
	}
	return nil
}
